#!/usr/bin/env python3
"""Deterministically integrate completed P1/P2 evidence into the active manuscript.

This script performs exact text replacements and refuses to edit if the expected
pre-integration text is absent. It does not alter numerical result files.
"""
from pathlib import Path

P = Path('paper/MANUSCRIPT_TOP_JOURNAL_POLISHED_20260911.md')
text = P.read_text(encoding='utf-8')

