for old, new in replacements:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f'Expected exactly one manuscript match, found {count}: {old[:100]!r}')
    text = text.replace(old, new)

P.write_text(text, encoding='utf-8')
print(f'P1_P2_MANUSCRIPT_INTEGRATION_PASS replacements={len(replacements)}')
